import { expect, test } from '@playwright/test';

import { navigate, signIn } from './helpers';

test('the proprietor sees the term at a glance and downloads the debtors list', async ({ page }) => {
  await signIn(page, 'proprietor@demo.schoolpay.ng', { mfa: true });

  // Bills may or may not have been generated by an earlier test in this run
  const generated = page.getByText('Money received per day');
  const empty = page.getByRole('link', { name: "Generate the term's bills" });
  await expect(generated.or(empty)).toBeVisible();
  if (await empty.isVisible()) {
    await empty.click();
    await page.getByRole('button', { name: 'Generate invoices' }).click();
    await page.getByRole('button', { name: 'Preview' }).click();
    await page.getByRole('button', { name: /^Generate \d+ invoices$/ }).click();
    await expect(page.getByText(/Done: \d+ invoices/)).toBeVisible();
    await page.getByRole('button', { name: 'Close' }).click();
    await page.getByRole('link', { name: 'Overview', exact: true }).click();
  }
  await expect(page.getByText('Billed', { exact: true }).first()).toBeVisible();
  await page.getByRole('tab', { name: 'By class' }).click();
  await expect(page.getByRole('region', { name: 'By class', exact: true }).getByRole('cell', { name: 'Primary 1' })).toBeVisible();

  await page.getByRole('link', { name: /students owe/ }).click();
  await expect(page.getByRole('heading', { name: 'Reports' })).toBeVisible();
  await expect(page.getByText(/\d+ students owe ₦/)).toBeVisible();
  const [excel] = await Promise.all([page.waitForEvent('download'), page.getByRole('button', { name: 'Download Excel' }).click()]);
  expect(excel.suggestedFilename()).toMatch(/^debtors-\d{4}-\d{2}-\d{2}\.xlsx$/);

  await page.getByRole('tab', { name: 'Money received' }).click();
  await expect(page.getByText('Net', { exact: true })).toBeVisible();
  const [pdf] = await Promise.all([page.waitForEvent('download'), page.getByRole('button', { name: 'Download PDF' }).click()]);
  expect(pdf.suggestedFilename()).toMatch(/^money-received-.+\.pdf$/);

  // Set-up pages live under the Setup menu
  await navigate(page, 'Fees');
  await expect(page.getByRole('heading', { name: 'Fees', exact: true })).toBeVisible();
});
